// components/SearchField.tsx
"use client";
export function SearchField() {
  const id = `search-${Math.random().toString(36).slice(2, 8)}`;
  return (
    <>
      <label htmlFor={id}>Search courses</label>
      <input id={id} type="search" />
    </>
  );
}

Browser console:
A tree hydrated but some attributes of the server rendered HTML didn't match the client properties. This won't be patched up.
  <label
+   htmlFor="search-k3f9qa"
-   htmlFor="search-0x7d2m"

Statement: "Replacing the random id with const id = useId() gives the same id on the server and in the browser, so this mismatch goes away and the label still points at its input."

// components/ContinueLink.tsx
"use client";
export function ContinueLink() {
  const last = typeof window !== "undefined" ? localStorage.getItem("lastLesson") : null;
  return (
    <a href={last ?? "/courses"}>
      {last ? "Continue where you left off" : "Browse courses"}
    </a>
  );
}

Statement: "Because the file starts with \"use client\", this component runs only in the browser, so the typeof window branch cannot cause a hydration mismatch."
